// Register .
// @router /user/register [POST]
func Register(ctx context.Context, c *app.RequestContext) {
	// 检查是否允许用户注册：管理后台"用户配置"持久化值优先，
	// 无记录回退 yaml（EffectiveUserSettings，修复管理端开关不生效）
	if !admin.EffectiveUserSettings(ctx).AllowUserRegistration {
		c.JSON(consts.StatusForbidden, map[string]interface{}{
			"code":    403,
			"message": "用户注册已关闭",
		})
		return
	}

	var err error
	var req usermodel.RegisterReq
	err = c.BindAndValidate(&req)
	if err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": err.Error(),
		})
		return
	}

	// 调用 service
	result, err := userService.Create(ctx, &userservice.CreateUserReq{
		Username: req.Username,
		Email:    req.Email,
		Password: req.Password,
		Nickname: req.Nickname,
	})
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": err.Error(),
		})
		return
	}

	resp := &usermodel.RegisterResp{
		Code:    200,
		Message: "注册成功",
		Data: &usermodel.UserData{
			ID:        int64(result.ID),
			Username:  result.Username,
			Email:     result.Email,
			Nickname:  result.Nickname,
			Avatar:    result.Avatar,
			Status:    int32(1),
			CreatedAt: result.CreatedAt.Format("2006-01-02 15:04:05"),
		},
	}

	c.JSON(consts.StatusOK, resp)
}

// Login .
// @router /user/login [POST]
func Login(ctx context.Context, c *app.RequestContext) {
	var err error
	var req usermodel.LoginReq
	err = c.BindAndValidate(&req)
	if err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": err.Error(),
		})
		return
	}

	// 失败锁定检查（维度 = IP + 账户名，防爆破）
	lock := middleware.GetDefaultLockout()
	lockKey := middleware.FormatLockKey("login", middleware.ClientIP(c), req.Username)
	if remain, locked := lock.CheckLocked(ctx, lockKey); locked {
		c.JSON(consts.StatusTooManyRequests, map[string]interface{}{
			"code":    errcode.CodeTooManyAttempts,
			"message": "尝试过于频繁，账户已临时锁定，请 " + strconv.Itoa(remain) + " 秒后重试",
		})
		return
	}

	// 调用 service 进行登录验证
	userInfo, token, err := userService.Login(ctx, req.Username, req.Password)
	if err != nil {
		_, _ = lock.RecordFailure(ctx, lockKey)
		c.JSON(consts.StatusUnauthorized, map[string]interface{}{
			"code":    401,
			"message": err.Error(),
		})
		return
	}
	lock.Reset(ctx, lockKey)

	resp := &usermodel.LoginResp{
		Code:    200,
		Message: "登录成功",
		Data: &usermodel.LoginData{
			Token: token,
			User: &usermodel.UserData{
				ID:        int64(userInfo.ID),
				Username:  userInfo.Username,
				Email:     userInfo.Email,
				Nickname:  userInfo.Nickname,
				Avatar:    userInfo.Avatar,
				Status:    int32(1),
				CreatedAt: userInfo.CreatedAt.Format("2006-01-02 15:04:05"),
			},
		},
	}

	c.JSON(consts.StatusOK, resp)
}

